package store

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"
)

var artifactIDPattern = regexp.MustCompile(`^[a-f0-9]{64}\.[a-zA-Z0-9]{1,10}$`)

// BuildArtifact is a file generated by the session's post-agent command.
type BuildArtifact struct {
	ID        string    `json:"id"`
	Name      string    `json:"name"`
	Size      int64     `json:"size"`
	SHA256    string    `json:"sha256"`
	CreatedAt time.Time `json:"createdAt"`
}

// BuildRecord records one post-agent command invocation for a round.
type BuildRecord struct {
	Round     int             `json:"round"`
	Command   string          `json:"command"`
	Directory string          `json:"directory"`
	Status    string          `json:"status"`
	StartedAt time.Time       `json:"startedAt"`
	EndedAt   time.Time       `json:"endedAt"`
	ExitCode  int             `json:"exitCode"`
	Error     string          `json:"error,omitempty"`
	Output    string          `json:"output,omitempty"`
	Artifacts []BuildArtifact `json:"artifacts,omitempty"`
}

// BuildRecord reads the latest build invocation for round n.
func (s *Store) BuildRecord(n int) (*BuildRecord, error) {
	var record BuildRecord
	err := readJSON(filepath.Join(s.RoundDir(n), "build.json"), &record)
	if err != nil {
		return nil, err
	}
	return &record, nil
}

// SaveBuildRecord writes the latest build invocation for round n.
func (s *Store) SaveBuildRecord(record *BuildRecord) error {
	if record.Round < 1 {
		return fmt.Errorf("invalid round %d", record.Round)
	}
	return writeJSON(filepath.Join(s.RoundDir(record.Round), "build.json"), record)
}

// PutBuildArtifact stores a build output under its content hash.
func (s *Store) PutBuildArtifact(round int, name string, data []byte, createdAt time.Time) (BuildArtifact, error) {
	name = filepath.Base(strings.ReplaceAll(name, "\\", "/"))
	if name == "." || name == "" {
		return BuildArtifact{}, fmt.Errorf("invalid artifact name")
	}
	ext := strings.TrimPrefix(filepath.Ext(name), ".")
	if !regexp.MustCompile(`^[a-zA-Z0-9]{1,10}$`).MatchString(ext) {
		return BuildArtifact{}, fmt.Errorf("unsupported artifact extension")
	}
	sum := sha256.Sum256(data)
	hash := hex.EncodeToString(sum[:])
	id := hash + "." + ext
	path := filepath.Join(s.RoundDir(round), "artifacts", id)
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return BuildArtifact{}, err
	}
	if err := writeFileAtomic(path, data); err != nil {
		return BuildArtifact{}, err
	}
	return BuildArtifact{ID: id, Name: name, Size: int64(len(data)), SHA256: hash, CreatedAt: createdAt}, nil
}

// ReadBuildArtifact only serves artifacts referenced by the round's build record.
func (s *Store) ReadBuildArtifact(round int, id string) ([]byte, string, error) {
	if !artifactIDPattern.MatchString(id) {
		return nil, "", fmt.Errorf("invalid artifact id")
	}
	record, err := s.BuildRecord(round)
	if err != nil {
		return nil, "", err
	}
	allowed := false
	for _, artifact := range record.Artifacts {
		if artifact.ID == id {
			allowed = true
			break
		}
	}
	if !allowed {
		return nil, "", fs.ErrNotExist
	}
	path := filepath.Join(s.RoundDir(round), "artifacts", id)
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, "", err
	}
	ext := strings.ToLower(filepath.Ext(id))
	mediaType := map[string]string{".pdf": "application/pdf", ".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".zip": "application/zip"}[ext]
	if mediaType == "" {
		mediaType = "application/octet-stream"
	}
	return data, mediaType, nil
}
